//! Books on the world's shelves (#104): short reads on the rules (drawn from
//! `docs/RULES.md`), the world and its Hexons (`docs/BESTIARY.md`,
//! `docs/bestiary/`, `docs/WORLD_DESIGN.md`) and a few tales, in English and
//! French. Maps place them as `{"kind": "book", "id": …}` interactions; a book
//! read is the progress flag `read_<id>`, so the save needs nothing new.

use crate::overworld::Progress;
use crate::T;

/// Which shelf a book belongs on: it picks the cover.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Family {
    /// How a duel is played.
    Rules,
    /// The world, its places and its Hexons.
    World,
    /// Stories told at the inns.
    Tales,
}

impl Family {
    pub fn name(self) -> &'static str {
        match self {
            Family::Rules => "rules",
            Family::World => "world",
            Family::Tales => "tales",
        }
    }

    pub fn label(self) -> T {
        match self {
            Family::Rules => T::new("Rules", "Règles"),
            Family::World => T::new("World", "Monde"),
            Family::Tales => T::new("Tales", "Contes"),
        }
    }
}

/// One spread: a heading and an illustration on the left page, the text on the right.
#[derive(Debug)]
pub struct Page {
    pub heading: T,
    pub text: T,
    /// The illustration: `card:<English card name>` (its art), `face:<type>`
    /// (`ember`, `tide`, `grove`, `storm`, `stone`, `dream`, `neutral`), `faces`
    /// (the six round a blank seventh), `board` (a duel table), or "" for none.
    pub art: &'static str,
}

#[derive(Debug)]
pub struct Book {
    pub id: &'static str,
    pub family: Family,
    pub title: T,
    pub pages: &'static [Page],
}

/// The type names an `face:` illustration may use.
pub const FACES: [&str; 7] = [
    "ember", "tide", "grove", "storm", "stone", "dream", "neutral",
];

const fn page(heading: T, text: T, art: &'static str) -> Page {
    Page { heading, text, art }
}

/// Every book, in the order the Journal's Library lists them.
pub static BOOKS: &[Book] = &[
    Book { id: "duel", family: Family::Rules, title: T::new("The Duel, Turn by Turn", "Le duel, tour par tour"), pages: &[
        page(T::new("A deck of sixty", "Un deck de soixante cartes"), T::new("Every duel begins with a deck of exactly sixty cards. No more than four may share a name, though basic energy is exempt and you may carry as many as you like. At least one card must be a Basic Hexon, the only kind that can enter play on its own. Around them you build the rest: Hexons that awaken, energy to fuel their attacks, and Trainers that draw, heal, search and switch. Shuffle well; the duel trusts the deck.", "Tout duel commence par un deck d'exactement soixante cartes. Pas plus de quatre exemplaires d'un même nom, sauf pour l'énergie de base, que l'on emporte à volonté. Il faut au moins un Hexon de Base, le seul qui puisse entrer en jeu par lui-même. Autour de lui, on bâtit le reste\u{a0}: des Hexons qui s'éveillent, de l'énergie pour leurs attaques, et des Dresseurs pour piocher, soigner, chercher et échanger. Mélangez bien\u{a0}: le duel fait confiance au deck."), "board"),
        page(T::new("The opening hand", "La main de départ"), T::new("Each player draws seven cards. A hand with no Basic Hexon cannot start a duel: reveal it, shuffle it back and draw seven again, as many times as it takes. You may not keep a hand without a Basic, and your opponent gains nothing from your bad luck: no bonus cards, ever. If neither player finds a Basic, both hands are shown and the whole setup starts over. Patience is part of the opening.", "Chaque joueur pioche sept cartes. Une main sans Hexon de Base ne peut pas ouvrir un duel\u{a0}: on la montre, on la remélange dans le deck et on en pioche sept autres, autant de fois qu'il le faut. Impossible de garder une main sans Base, et votre adversaire ne gagne rien à votre malchance\u{a0}: jamais la moindre carte en prime. Si aucun des deux joueurs n'a de Base, les deux mains sont montrées et toute la mise en place recommence. La patience fait partie de l'ouverture."), "card:Lucky Satchel"),
        page(T::new("Setting the table", "La mise en place"), T::new("Place one Basic as your Active Hexon: it attacks and takes the blows. Then put up to five more Basics on your Bench, or none at all. Next, set aside the top six cards of your deck, face down: those are your Prizes. Only then is a coin flipped to decide who plays first, and the winner of the toss gets no choice. From the very first turn, each player draws one card as their turn begins.", "Posez un Hexon de Base en Actif\u{a0}: c'est lui qui attaque et qui encaisse. Placez ensuite jusqu'à cinq autres Hexons de Base sur votre Banc, ou aucun. Mettez de côté, faces cachées, les six premières cartes de votre deck\u{a0}: ce sont vos Récompenses. Alors seulement, une pièce décide qui commence, sans laisser le choix à personne. Dès le tout premier tour, chaque joueur pioche une carte au début de son tour."), "board"),
        page(T::new("Your turn", "Votre tour"), T::new("After the draw comes the heart of the turn, in whatever order you like. Put Basics on your Bench, attach one energy card, play as many Trainers as you wish, use your Hexons' Powers, awaken them, retreat once. Then attack, or simply end the turn. Attacking always ends it, so do everything else first. One rule is Sixfold's own: whoever goes first cannot attack on their very first turn. Build instead.", "Après la pioche vient le cœur du tour, dans l'ordre qui vous plaît. Posez des Hexons de Base sur le Banc, attachez une carte Énergie, jouez autant de Dresseurs que vous voulez, utilisez les Pouvoirs de vos Hexons, éveillez-les, battez en retraite une fois. Puis attaquez, ou finissez simplement le tour. Une attaque y met toujours fin\u{a0}: faites tout le reste avant. Une règle est propre à Sixfold\u{a0}: qui commence ne peut pas attaquer à son tout premier tour. On s'installe."), "card:Relay Baton"),
        page(T::new("How a duel is won", "Comment on gagne"), T::new("Each time you knock out one of your opponent's Hexons, take one of your Prizes into your hand. Take the last one and you win. You also win if your opponent's Active falls with nobody left on the Bench to replace it, or if their deck is empty when they must draw at the start of their turn. When both players win at the same moment, the duel turns to sudden death: a fresh setup, one Prize each, first to take it wins.", "Chaque fois que vous mettez K.O. un Hexon adverse, prenez une de vos Récompenses en main. Prenez la dernière, et vous gagnez. Vous gagnez aussi si l'Actif adverse tombe sans personne sur le Banc pour le remplacer, ou si votre adversaire n'a plus de carte à piocher au début de son tour. Si les deux joueurs gagnent au même instant, place à la mort subite\u{a0}: nouvelle mise en place, une Récompense chacun, et le premier qui la prend l'emporte."), "board"),
    ]},
    Book { id: "energy", family: Family::Rules, title: T::new("Energy, Awakening and Retreat", "Énergie, Éveil et retraite"), pages: &[
        page(T::new("One energy a turn", "Une énergie par tour"), T::new("Once each turn, you may attach one energy card from your hand to any of your Hexons, Active or Benched. It stays there until something discards it. Energy you attach to the Bench today is an attack ready tomorrow, so think a turn ahead. You may attach on your very first turn, even when you go first and cannot attack yet. A turn without an attachment is usually a turn wasted.", "Une fois par tour, vous pouvez attacher une carte Énergie de votre main à l'un de vos Hexons, Actif ou sur le Banc. Elle y reste jusqu'à ce qu'un effet la défausse. L'énergie posée aujourd'hui sur le Banc, c'est l'attaque prête demain\u{a0}: pensez un tour à l'avance. Vous pouvez attacher dès votre premier tour, même si vous commencez et ne pouvez pas encore attaquer. Un tour sans énergie attachée est souvent un tour perdu."), "card:Fire Energy"),
        page(T::new("Paying for an attack", "Payer une attaque"), T::new("Every attack shows its cost in energy symbols. A coloured symbol must be paid with energy of that colour. A Neutral symbol takes anything: a spare Ember or Tide energy pays it just as well. Twofold Energy counts as two at once, but only ever as Neutral, so it never pays a coloured symbol. Attacking does not use energy up: it stays attached for the next turn, unless the attack itself tells you to discard it.", "Chaque attaque affiche son coût en symboles d'énergie. Un symbole de couleur se paie avec une énergie de cette couleur. Un symbole Neutre accepte tout\u{a0}: une énergie Braise ou Marée en trop le paie très bien. L'Énergie Double compte pour deux d'un coup, mais toujours comme du Neutre\u{a0}: elle ne paie jamais un symbole de couleur. Attaquer ne consomme pas l'énergie\u{a0}: elle reste attachée pour le tour suivant, sauf si l'attaque elle-même demande de la défausser."), "card:Twofold Energy"),
        page(T::new("Awakening", "L'Éveil"), T::new("A Basic awakens into Awaken 1, and some lines go on to Awaken 2. Play the card on the Hexon named after \"Awakens from\". Neither player can awaken on their first turn, no Hexon can awaken on the turn it came into play, and each Hexon awakens only once a turn. Damage and attached cards stay where they are. An Active that awakens shakes off every special condition at once.", "Un Hexon de Base s'éveille en Éveil 1, et certaines lignées vont jusqu'à l'Éveil 2. Jouez la carte sur le Hexon nommé après «\u{a0}S'éveille de\u{a0}». Personne ne peut éveiller à son premier tour, aucun Hexon ne s'éveille le tour où il est entré en jeu, et chaque Hexon ne s'éveille qu'une fois par tour. Les dégâts et les cartes attachées restent en place. Un Actif qui s'éveille se libère d'un coup de tous ses états spéciaux."), "card:Flarrow"),
        page(T::new("Retreat", "Battre en retraite"), T::new("Once a turn, your Active may retreat to the Bench and let another Hexon take its place. Pay the retreat cost by discarding energy attached to the Hexon that leaves; Twofold Energy pays two. Retreating does not end your turn, and the newcomer may attack. The one leaving shakes off its special conditions. An Asleep or Paralyzed Hexon cannot retreat at all, and a Confused one pays first, then flips a coin: tails, it stays.", "Une fois par tour, votre Actif peut battre en retraite sur le Banc et laisser sa place à un autre Hexon. Payez le coût de Retraite en défaussant de l'énergie attachée au Hexon qui part\u{a0}; l'Énergie Double en paie deux. La retraite ne finit pas le tour, et le nouveau venu peut attaquer. Celui qui s'en va perd ses états spéciaux. Un Hexon Endormi ou Paralysé ne peut pas battre en retraite\u{a0}; un Hexon Confus paie d'abord, puis lance une pièce\u{a0}: pile, il reste."), "card:Relay Baton"),
    ]},
    Book { id: "conditions", family: Family::Rules, title: T::new("Conditions and Damage", "États spéciaux et dégâts"), pages: &[
        page(T::new("Asleep and Paralyzed", "Endormi et Paralysé"), T::new("An Asleep Hexon can neither attack nor retreat. Between turns its owner flips a coin: heads, it wakes up; tails, it dozes on, and the coin comes round again after the next turn. A Paralyzed Hexon is just as stuck, but no coin is needed: the paralysis lasts through one of its owner's turns, then wears off by itself. Either way it is a sitting target, so plan your Bench around it.", "Un Hexon Endormi ne peut ni attaquer ni battre en retraite. Entre les tours, son joueur lance une pièce\u{a0}: face, il se réveille\u{a0}; pile, il somnole encore, et la pièce revient après le tour suivant. Un Hexon Paralysé est tout aussi bloqué, mais sans pièce\u{a0}: la paralysie dure un tour de son joueur, puis disparaît d'elle-même. Dans les deux cas, c'est une cible immobile\u{a0}: prévoyez votre Banc en conséquence."), "card:Dozel"),
        page(T::new("Confused", "Confus"), T::new("A Confused Hexon may still attack, but it flips a coin first. Heads, the attack goes through as normal; tails, the attack fails, it takes 20 damage itself, and the turn is over all the same. Retreating costs a coin too: pay the energy, then flip, and on tails it stays put with the energy gone. Confusion never fades on its own. It lasts until the Hexon leaves the Active spot, awakens or is cured.", "Un Hexon Confus peut encore attaquer, mais il lance d'abord une pièce. Face, l'attaque se déroule normalement\u{a0}; pile, elle échoue, il subit lui-même 20 dégâts, et le tour s'achève quand même. La retraite aussi se joue à pile ou face\u{a0}: on paie l'énergie, on lance la pièce, et sur pile il reste en place, l'énergie perdue. La confusion ne passe jamais d'elle-même\u{a0}: elle dure jusqu'à ce que le Hexon quitte la place d'Actif, s'éveille ou soit soigné."), "face:dream"),
        page(T::new("Poisoned", "Empoisonné"), T::new("A Poisoned Hexon takes 10 damage between every turn, after yours and after your opponent's alike. Some attacks double-poison: then it is 20 each time. Poison never wears off on its own, and unlike the other conditions it stops nothing: a Poisoned Hexon may still attack, retreat and use its Power. It can sit alongside sleep, paralysis or confusion. A Hexon that falls to poison between turns still gives up a Prize.", "Un Hexon Empoisonné subit 10 dégâts entre chaque tour, après le vôtre comme après celui de votre adversaire. Certaines attaques empoisonnent doublement\u{a0}: c'est alors 20 à chaque fois. Le poison ne s'en va jamais tout seul et, contrairement aux autres états, il n'empêche rien\u{a0}: un Hexon Empoisonné peut encore attaquer, battre en retraite et utiliser son Pouvoir. Il s'ajoute volontiers au sommeil, à la paralysie ou à la confusion. Un Hexon qui succombe au poison entre deux tours rapporte quand même une Récompense."), "card:Venom Dart"),
        page(T::new("Only the Active", "Seul l'Actif"), T::new("Special conditions only ever sit on the Active Hexon. A Benched Hexon cannot be Asleep, Paralyzed, Confused or Poisoned, which is why the cure is so often a step back: the moment a Hexon leaves the Active spot, every condition on it is gone. Awakening the Active clears them too, and so do a few Trainers. While it is Asleep, Paralyzed or Confused, an Active cannot use its Power either.", "Les états spéciaux ne touchent jamais que l'Actif. Un Hexon du Banc ne peut être ni Endormi, ni Paralysé, ni Confus, ni Empoisonné\u{a0}: voilà pourquoi le remède est si souvent un pas en arrière. Dès qu'un Hexon quitte la place d'Actif, tous ses états disparaissent. Éveiller l'Actif les efface aussi, tout comme certains Dresseurs. Tant qu'il est Endormi, Paralysé ou Confus, un Actif ne peut pas non plus utiliser son Pouvoir."), "card:Clearwater Vial"),
        page(T::new("Counting damage", "Compter les dégâts"), T::new("Damage is worked out in a fixed order. Start from the attack's printed damage, then apply the attacker's own doubling if it has one. Weakness doubles the result; Resistance takes away 30. Then add 10 for each damage-boosting Trainer on the attacker and remove 20 for each shielding Trainer on the defender. Below zero counts as zero. Damage an effect deals to the Bench ignores Weakness and Resistance. Each knocked-out Hexon gives one Prize.", "Les dégâts se calculent dans un ordre fixe. On part des dégâts imprimés de l'attaque, puis on applique le doublement propre à l'attaquant s'il en a un. La Faiblesse double le résultat\u{a0}; la Résistance retire 30. On ajoute ensuite 10 pour chaque Dresseur offensif attaché à l'attaquant et on retire 20 pour chaque Dresseur protecteur attaché au défenseur. Sous zéro, on compte zéro. Les dégâts qu'un effet inflige au Banc ignorent Faiblesse et Résistance. Chaque Hexon mis K.O. rapporte une Récompense."), "board"),
    ]},
    Book { id: "six_faces", family: Family::World, title: T::new("The Six Faces", "Les six faces"), pages: &[
        page(T::new("A world cut like a stone", "Un monde taillé comme une pierre"), T::new("The old wardens say the world was cut like a seal stone, with six faces: Ember, Tide, Grove, Storm, Stone and Dream. Everything alive carries a little of one face. In a Hexon, the face has taken root. That is the whole difference between a Hexon and the hare or heron it calls to mind: something of the world has settled in it and begun, very slowly, to grow.", "Les anciens gardiens disent que le monde fut taillé comme une pierre de sceau, à six faces\u{a0}: Braise, Marée, Bosquet, Orage, Roc et Songe. Tout ce qui vit porte un peu d'une face. Chez un Hexon, la face a pris racine. Toute la différence entre un Hexon et le lièvre ou le héron qu'il rappelle tient là\u{a0}: quelque chose du monde s'est installé en lui et s'est mis, très lentement, à pousser."), "faces"),
        page(T::new("Grain", "Le grain"), T::new("Each face has its grain, the stuff a Hexon is slowly made of. Ember brings kiln clay, Tide brings sea glass, Grove brings bark. Storm brings copper and mica, Stone brings rock strata, and Dream brings lantern gauze, lit from within. Grain grows over the shape of an ordinary beast the way frost grows over a twig, until the animal underneath survives only in the silhouette: a crest, an ear, the curl of a tail.", "Chaque face a son grain, la matière dont un Hexon se fait peu à peu. La Braise apporte l'argile de four, la Marée le verre de mer, le Bosquet l'écorce. L'Orage apporte le cuivre et le mica, le Roc les strates de roche, le Songe la gaze de lanterne, éclairée de l'intérieur. Le grain recouvre la forme d'une bête ordinaire comme le givre recouvre une brindille, jusqu'à ce que l'animal ne survive plus que dans la silhouette\u{a0}: une crête, une oreille, une queue enroulée."), "card:Cindrel"),
        page(T::new("The blank seventh face", "La septième face"), T::new("On every seal stone, a seventh face sits on top, smooth and blank. It belongs to the Neutral Hexons, who carry no grain at all: only the plain stuff of the meadow and the road, patchwork felt, thread, chalk and unglazed porcelain. They live wherever the six roads meet. Having no face of their own, each line grew the shape of a traveller's tool: a bellows, a hearing horn, a pincushion, a spool.", "Sur chaque pierre de sceau, une septième face coiffe les six autres, lisse et nue. Elle appartient aux Hexons Neutres, qui ne portent aucun grain\u{a0}: seulement la matière simple du pré et de la route, feutre en patchwork, fil, craie et porcelaine brute. Ils vivent là où les six routes se croisent. Faute de face à eux, chaque lignée a pris la forme d'un outil de voyageur\u{a0}: un soufflet, un cornet acoustique, une pelote à épingles, une bobine."), "face:neutral"),
        page(T::new("One night's Awakening", "L'Éveil d'une nuit"), T::new("A Hexon does not grow up; it awakens. When it has drunk enough of its face, a kiln's heat, a storm's charge, a spring tide, a long dream, its grain spreads through its whole body in a single night. A Basic becomes Awaken 1, and some lines go on to Awaken 2. As for seal stone itself, it is grain without a body: the Facets in your purse are chips of it.", "Un Hexon ne grandit pas\u{a0}: il s'éveille. Quand il a bu assez de sa face, la chaleur d'un four, la charge d'un orage, une grande marée, un long rêve, son grain gagne tout son corps en une seule nuit. Le Hexon de Base devient Éveil 1, et certaines lignées vont jusqu'à l'Éveil 2. Quant à la pierre de sceau, c'est du grain sans corps\u{a0}: les Facettes de votre bourse en sont des éclats."), "card:Pyrequill"),
    ]},
    Book { id: "night_sky", family: Family::World, title: T::new("The Sky over Sixfold", "Le ciel de Sixfold"), pages: &[
        page(T::new("The Ring of Six", "L'Anneau des Six"), T::new("On a clear night, look straight up from the meadow and you will find six bright stars set in a ring, each with a faint tint of its own: amber, sea green, leaf, white-blue, ochre, lilac. Stargazers call them the Six and name them after the faces. In the middle of the ring lies a gap that looks dark to most eyes. The patient swear a seventh star hides there, too faint to be sure of.", "Par nuit claire, levez les yeux depuis le pré\u{a0}: six étoiles brillantes y forment un anneau, chacune d'une teinte légère, ambre, vert d'eau, feuille, blanc bleuté, ocre, lilas. Les guetteurs d'étoiles les appellent les Six et leur donnent le nom des faces. Au milieu de l'anneau s'ouvre un vide qui paraît noir à la plupart des yeux. Les plus patients jurent qu'une septième étoile s'y cache, trop pâle pour qu'on en soit sûr."), "faces"),
        page(T::new("The chart and its question", "La carte et sa question"), T::new("Up at Stormwatch, the observatory keeps a star chart on its light table, pinned flat with brass weights. Six stars are ringed in red ink. The seventh, faint, has only a question mark beside it, and the astronomer who keeps the great telescope forgets to sleep trying to answer it. On some nights, she says, the lens shows every star doubled, as if the sky had a crack in it.", "Là-haut, à Guette-Orage, l'observatoire garde une carte du ciel sur sa table lumineuse, tenue à plat par des poids de laiton. Six étoiles y sont cerclées d'encre rouge. La septième, pâle, n'a droit qu'à un point d'interrogation, et l'astronome qui veille sur la grande lunette en oublie de dormir pour y répondre. Certaines nuits, dit-elle, la lentille montre chaque étoile en double, comme si le ciel était fêlé."), "card:Squallkite"),
        page(T::new("Four turns of the day", "Les quatre temps du jour"), T::new("The day in Sixfold turns through four phases. Dawn comes up pink from the east, and the bakers are already at their ovens. Day is long and plain and good for walking. At dusk the light goes copper in the west and the lamps come on. Night is blue and deep. Every inn will let you rest until whichever phase you need, so nothing that lives in the dark is ever more than one good sleep away.", "À Sixfold, la journée tourne en quatre temps. L'aube se lève rose à l'est, et les boulangers sont déjà au four. Le jour est long, simple, bon pour la marche. Au crépuscule, la lumière vire au cuivre à l'ouest et les lampes s'allument. La nuit est bleue et profonde. Chaque auberge vous laisse dormir jusqu'au moment voulu\u{a0}: rien de ce qui vit dans le noir n'est jamais à plus d'une bonne nuit de sommeil."), "face:dream"),
        page(T::new("Who wakes at night", "Ceux qui veillent la nuit"), T::new("Some things only happen after dark. In every region one duelist comes out at night alone, and their purse is heavier for the trouble. Things you will never find by day turn up in the glow: moths at the lamps, a gleam in cooling ash, pools left by the low tide. Townsfolk keep other hours too: the angler moves to the pier, the shops hang up their signs. Bring a lantern, and your best deck.", "Certaines choses n'arrivent qu'à la nuit tombée. Dans chaque région, un duelliste ne sort qu'une fois le soleil couché, et sa bourse est plus lourde pour la peine. Ce qu'on ne trouve jamais de jour apparaît dans la lueur\u{a0}: des phalènes aux lampes, un éclat dans la cendre qui refroidit, des flaques laissées par la marée basse. Les habitants changent d'heures aussi\u{a0}: le pêcheur passe sur la jetée, les boutiques accrochent leur pancarte. Prenez une lanterne, et votre meilleur deck."), "card:Gloamowl"),
        page(T::new("Lightning and lanterns", "Éclairs et lanternes"), T::new("Two regions own the night sky. Over the Galewold, lightning walks far out at sea without a sound, lighting the Rodspire white for a heartbeat while the pylons hum back. Over the Hushlands the sky stays soft, and the light comes from below: paper lanterns drift on Lanternmere's lake, and at night a line of them makes a path across the water. The Six, they say, look down most fondly on those two.", "Deux régions règnent sur le ciel nocturne. Sur les Hautes-Rafales, la foudre marche au loin sur la mer sans un bruit, blanchit l'Aiguille-Foudre le temps d'un battement de cœur, et les pylônes lui répondent en bourdonnant. Sur les Terres du Murmure, le ciel reste doux et la lumière vient d'en bas\u{a0}: à Lac-aux-Lanternes, des lanternes de papier dérivent sur le lac et, la nuit, leur file trace un chemin sur l'eau. Les Six, dit-on, regardent ces deux-là avec tendresse."), "card:Moonmoth"),
    ]},
    Book { id: "duel_hall", family: Family::World, title: T::new("The Duel Hall", "La salle de duel"), pages: &[
        page(T::new("Where the roads begin", "Là où partent les routes"), T::new("The duel hall stands on Sixfold Meadow, where the six roads start, one for each face. Everybody plays their first duel at one of its tables, and most people their second, third and fortieth too. Wynne runs the pack counter: she remembers every customer, prices everything in Facets and gives away more than she sells. Mind the rug on the way in. It is older than she is, and she will tell you so.", "La salle de duel se dresse sur le Pré de Sixfold, là où partent les six routes, une par face. Tout le monde y joue son premier duel, et la plupart y jouent aussi le deuxième, le troisième et le quarantième. Wynne tient le comptoir des boosters\u{a0}: elle se souvient de chaque client, affiche ses prix en Facettes et donne plus qu'elle ne vend. Attention au tapis en entrant\u{a0}: il est plus vieux qu'elle, et elle vous le dira."), "board"),
        page(T::new("The Field Register", "Le Registre de terrain"), T::new("In the back room, Sable the Hex Warden keeps the Field Register. Every warden, ranger and duelist who walks the ring sends back what they saw, and Sable boils it down to a single line per Hexon: where it lives, what it does, what the locals say about it. The lines are short because the Register is long. Read enough of them and you start to know the ring before you have walked it.", "Dans l'arrière-salle, Sable, la Gardienne des Six, tient le Registre de terrain. Chaque gardien, garde forestier ou duelliste qui parcourt l'anneau y envoie ce qu'il a vu, et Sable le réduit à une seule ligne par Hexon\u{a0}: où il vit, ce qu'il fait, ce qu'on en dit sur place. Les lignes sont courtes parce que le Registre est long. À force de les lire, on finit par connaître l'anneau avant de l'avoir parcouru."), "card:Field Guide"),
        page(T::new("The sealed door", "La porte scellée"), T::new("At the back of the hall is a door nobody opens. Six empty hexagons are cut into it, one for each face. Out on the ring, at each region's seal site, stands a seal stone, and beside it a rival who keeps it. Win there and you carry a seal home. Six seals fill six hexagons, and what waits behind the door is between you and the Warden. Wynne only smiles and says she sweeps up after.", "Au fond de la salle, il y a une porte que personne n'ouvre. Six hexagones vides y sont gravés, un par face. Sur l'anneau, au site de sceau de chaque région, se dresse une pierre de sceau, et près d'elle un rival qui la garde. Gagnez là-bas et vous rapportez un sceau. Six sceaux remplissent six hexagones, et ce qui attend derrière la porte ne regarde que vous et la Gardienne. Wynne se contente de sourire\u{a0}: elle dit qu'elle balaie après."), "faces"),
        page(T::new("Six rivals", "Six rivaux"), T::new("Six rivals keep the six seals. Bramble tends the hedges of the Elder Ring and plays Grove, patient as a growing leaf. Marlo plays Tide and reads the currents of the Saltreach. Cinza plays Ember, runs the Kilnmouth and never waits. Quill plays Storm, logs the Galewold's weather and aims at your Bench. Orla plays Stone and runs the Bastion's quarry. Lumen plays Dream and gardens the Moonwell by night. Each is fair; none is easy.", "Six rivaux gardent les six sceaux. Bramble soigne les haies du Cercle des Anciens et joue Bosquet, patient comme une feuille qui pousse. Marlo joue Marée et lit les courants de la Côte Salée. Cinza joue Braise, court la Gueule-du-Four et n'attend jamais. Quill joue Orage, consigne le temps des Hautes-Rafales et vise votre Banc. Orla joue Roc et dirige la carrière du Bastion. Lumen joue Songe et jardine le Puits-de-Lune la nuit. Tous sont loyaux, aucun n'est facile."), "faces"),
    ]},
    Book { id: "ring_of_regions", family: Family::World, title: T::new("Round the Ring", "Le tour de l'anneau"), pages: &[
        page(T::new("A guide for the road", "Guide pour la route"), T::new("Six roads leave Sixfold Meadow, and if you keep walking, each one brings you to the next region and, in the end, home again. That loop is what travellers call the ring. Every region has a road in, a town with an inn and, at the far end, a seal site. Waymark stones stand in each town and at each seal site: touch one once, and you can travel back to it whenever you like.", "Six routes quittent le Pré de Sixfold et, à force de marcher, chacune vous mène à la région voisine puis, au bout du compte, chez vous. C'est cette boucle que les voyageurs appellent l'anneau. Chaque région a sa route d'arrivée, une ville avec son auberge et, tout au bout, un site de sceau. Des bornes se dressent dans chaque ville et sur chaque site de sceau\u{a0}: touchez-en une une fois, et vous pourrez y revenir quand vous voudrez."), "faces"),
        page(T::new("Emberlands and Galewold", "Braisières et Hautes-Rafales"), T::new("The Emberlands are black basalt terraces and ash-grey ground, glass glinting everywhere. Climb out of Emberstep Quarry to Cinderwick, a glassblowers' town round its Great Kiln, then on to the Kilnmouth, a cooled crater whose vents steam all day. East lies the Galewold: high heath on sea cliffs, dry-stone walls, chime posts humming in the wind across the Thrumming Downs. Stormwatch keeps its observatory on the bluff, and the Rodspire stands out at sea.", "Les Braisières, ce sont des terrasses de basalte noir et une terre gris cendre où le verre scintille partout. De la Carrière de Pas-de-Braise, on monte à Mèche-Cendre, ville de souffleurs de verre autour de son Grand Four, puis à la Gueule-du-Four, un cratère refroidi dont les évents fument tout le jour. À l'est s'étendent les Hautes-Rafales\u{a0}: lande sur falaises, murets de pierre sèche, poteaux à carillons qui chantent au vent sur les Landes Vibrantes. Guette-Orage garde son observatoire sur l'à-pic, et l'Aiguille-Foudre se dresse en mer."), "face:ember"),
        page(T::new("Saltreach and Hushlands", "Côte Salée et Terres du Murmure"), T::new("The Saltreach is harbour life on stilts: nets drying, painted boats, a gull on every post. Saltwind Boardwalk leads to Gullhaven, a horseshoe harbour with a fish market, and beyond it to the Bellflats, where the sea goes out by day round a drowned bell tower. The Hushlands are willow country in a soft, endless twilight. Hushwillow Lane runs down to Lanternmere and its lake of floating lanterns; the Moonwell Garden only truly wakes at night.", "La Côte Salée, c'est la vie de port sur pilotis\u{a0}: filets qui sèchent, barques peintes, une mouette sur chaque poteau. La Promenade de Ventsalé mène à Havre-aux-Mouettes, port en fer à cheval et son marché aux poissons, puis aux Grèves de la Cloche, où la mer se retire le jour autour d'un clocher englouti. Les Terres du Murmure sont un pays de saules baigné d'un crépuscule sans fin. L'Allée des Saules-Murmures descend vers Lac-aux-Lanternes et son lac de lanternes flottantes\u{a0}; le Jardin du Puits-de-Lune ne s'éveille vraiment que la nuit."), "face:tide"),
        page(T::new("Deepgrove and Stonebacks", "Bois-Profond et Échines de Pierre"), T::new("The Deepgrove is old forest grown huge, moss on everything, bees in the light. Fernhollow Trail leads to Rootholm, a village built in the roots of a fallen elder, with walkways up in the canopy, and on to the Elder Ring, a hedge maze ringed by standing trees. The Stonebacks are slate mountains and mining terraces. The Undermine runs dark beneath them; Scree Pass climbs to Anvilstead and its headframe, and the Bastion keeps its menhirs on the top terrace.", "Le Bois-Profond est une vieille forêt devenue immense, de la mousse partout, des abeilles dans la lumière. Le Sentier de Creuse-Fougère mène à Racinemont, un village bâti dans les racines d'un géant tombé, avec des passerelles dans la canopée, puis au Cercle des Anciens, un labyrinthe de haies cerné d'arbres dressés. Les Échines de Pierre sont des montagnes d'ardoise et des terrasses minières. Les Galeries Basses courent dans le noir sous leurs pentes\u{a0}; le Col des Éboulis grimpe jusqu'à Bourg-l'Enclume et son chevalement, et le Bastion garde ses menhirs tout en haut."), "face:grove"),
    ]},
    Book { id: "field_notes", family: Family::World, title: T::new("Hexon Field Notes", "Notes de terrain sur les Hexons"), pages: &[
        page(T::new("Reading a Hexon", "Lire un Hexon"), T::new("Every Hexon is built from three things. First, an animal base, kept only in the silhouette and a trait or two: the crest of a hoopoe, the ears of a fawn. Second, the grain of its face, the material it is slowly turning into. Third, one organ of its own line that no real animal has. Learn to see all three and you will never mistake a Hexon for a bird, a frog or a hare again.", "Tout Hexon se construit à partir de trois choses. D'abord, une base animale, qui ne survit que dans la silhouette et un trait ou deux\u{a0}: la crête d'une huppe, les oreilles d'un faon. Ensuite, le grain de sa face, la matière qu'il devient peu à peu. Enfin, un organe propre à sa lignée, qu'aucun animal réel ne possède. Apprenez à voir les trois, et vous ne confondrez plus jamais un Hexon avec un oiseau, une grenouille ou un lièvre."), "faces"),
        page(T::new("Seams, rings and buds", "Fêlures, anneaux et bourgeons"), T::new("Each face leaves a sign that recurs across its lines. Ember Hexons show glowing seams, hairline cracks in their glaze lit from an ember core. Look at a Cindrel: a soot-grey chick still wearing half its terracotta egg like a pot, its crest of clay quills tipped with live embers. Tide Hexons carry tide rings, pale ripple bands across the hide. Grove Hexons bear buds that stay shut on a Basic and open as the line awakens.", "Chaque face laisse un signe qui revient d'une lignée à l'autre. Les Hexons Braise portent des fêlures lumineuses, fines craquelures de leur glaçure éclairées par un cœur de braise. Regardez un Braisillon\u{a0}: un oisillon gris suie qui porte encore la moitié de son œuf de terre cuite comme un pot, la crête hérissée de piquants d'argile au bout rougeoyant. Les Hexons Marée portent des anneaux de marée, pâles ondes sur la peau. Les Hexons Bosquet ont des bourgeons, fermés chez un Hexon de Base, qui s'ouvrent au fil des Éveils."), "card:Cindrel"),
        page(T::new("Prongs, strata and motes", "Pointes, strates et lueurs"), T::new("Storm Hexons carry copper prongs in pairs, and a spark always jumps between them: a Sparkit is a slim, stoat-shaped thing in slate felt, its two prongs crackling. Stone Hexons wear strata, layered bands of rock like a cliff face. Dream Hexons are circled by small glowing motes. Neutral Hexons have no grain, so they carry living chalk instead: markings that mean something, a tunnel map, a route home, a tally of loads.", "Les Hexons Orage portent des pointes de cuivre par paires, entre lesquelles saute toujours une étincelle\u{a0}: un Étincelot, c'est une petite bête de feutre ardoise à silhouette d'hermine, ses deux pointes crépitantes. Les Hexons Roc portent des strates, bandes de roche empilées comme une falaise. Autour des Hexons Songe tournent de petites lueurs. Les Hexons Neutres n'ont pas de grain\u{a0}: ils portent à la place une craie vivante, des marques qui disent quelque chose, un plan de galerie, un chemin de retour, un compte de charges."), "card:Sparkit"),
        page(T::new("What Awakening keeps", "Ce que l'Éveil garde"), T::new("Awakening never wipes a Hexon clean. It keeps the colours, markings and signature parts of the stage before and enlarges them, so you can always tell a line. A Sprigget is a seed pod on root legs, buds shut along its back. As a Thornbuck its bark has plated over and leaves burst from the seams. As an Elderhart it carries a small tree in blossom on its head, and rangers say it only sets off walking when the forest is wounded.", "L'Éveil n'efface jamais un Hexon. Il garde les couleurs, les marques et les parties distinctives du stade précédent, en les amplifiant\u{a0}: on reconnaît toujours une lignée. Un Brindelet est une cosse sur pattes de racines, des bourgeons fermés le long du dos. Devenu Brocépine, son écorce s'est cuirassée et des feuilles jaillissent des jointures. Devenu Sylvecerf, il porte sur la tête un petit arbre en fleurs, et les gardes forestiers disent qu'il ne se met en route que lorsque la forêt est blessée."), "card:Elderhart"),
        page(T::new("A ranger's tip", "Un conseil de garde forestier"), T::new("Never trust colour alone; trust shape. Glaze can pass for glass at dusk, and felt for stone in the rain. Read the silhouette first, then the grain, then hunt for the one impossible organ. A Pocketmouse, for instance, has no body to speak of, only a ball of its own wound thread, and more than one lost traveller has found the way out by following the loose end. Write down what you see. Sable reads everything.", "Ne vous fiez jamais à la couleur seule, fiez-vous à la forme. Au crépuscule, une glaçure passe pour du verre\u{a0}; sous la pluie, du feutre passe pour de la pierre. Lisez d'abord la silhouette, puis le grain, puis cherchez l'organe impossible. Une Souripoche, par exemple, n'a pour ainsi dire pas de corps\u{a0}: rien qu'une pelote de son propre fil, et plus d'un voyageur égaré s'en est sorti en suivant le bout qui dépasse. Notez ce que vous voyez. Sable lit tout."), "card:Pocketmouse"),
    ]},
    Book { id: "seventh_face", family: Family::World, title: T::new("Rook's Notebook", "Le carnet de Rook"), pages: &[
        page(T::new("Twelve, and no colour", "Douze ans, pas de couleur"), T::new("I was twelve when I took my first deck to the hall. I lost to everyone. Everyone. Even the boy who shuffled with his elbows. Wynne patted my shoulder and said I'd find my colour one day. Nice of her. Wrong, but nice. I tried Ember, Tide, Grove, the lot, and nothing stuck. So I stopped looking for a colour and started playing the cards nobody else wanted: the Neutrals.", "J'avais douze ans quand j'ai apporté mon premier deck à la salle. J'ai perdu contre tout le monde. Tout le monde. Même le gamin qui mélangeait avec les coudes. Wynne m'a tapoté l'épaule en disant que je trouverais ma couleur un jour. Gentil de sa part. Faux, mais gentil. J'ai essayé Braise, Marée, Bosquet, tout, et rien n'a pris. Alors j'ai arrêté de chercher une couleur et je me suis mis à jouer les cartes dont personne ne voulait\u{a0}: les Neutres."), "face:neutral"),
        page(T::new("The wrong way round", "Le tour à l'envers"), T::new("Everyone walks the ring the same way, so I walked it the other way. Every year. Fewer queues at the inns, and nobody to measure myself against. I counted the seal stones: six of them, six faces each, and on top a seventh, smooth, that nobody ever carves. The wardens shrug. The innkeepers change the subject. A face nobody claims, for a duelist with no colour. You can see where I was going with this.", "Tout le monde fait le tour de l'anneau dans le même sens, alors je l'ai fait dans l'autre. Chaque année. Moins de monde aux auberges, et personne à qui me comparer. J'ai compté les pierres de sceau\u{a0}: six, six faces chacune, et dessus une septième, lisse, que personne ne grave jamais. Les gardiens haussent les épaules. Les aubergistes changent de sujet. Une face que personne ne réclame, pour un duelliste sans couleur. On voit où je voulais en venir."), "card:Burrowbit"),
        page(T::new("The tally on my sleeve", "Le compte sur ma manche"), T::new("Then someone new turned up at the hall with a single seal and a look I knew. I kept a tally of their wins on my sleeve, in chalk, to stay honest. It got long. Stormwatch, Lanternmere: every time I looked over my shoulder, there they were again. Nobody had ever caught up with me before. I told myself it was annoying. I am writing down here, where nobody will read it, that it wasn't.", "Et puis quelqu'un est arrivé à la salle avec un seul sceau et un regard que je connaissais. J'ai tenu le compte de ses victoires sur ma manche, à la craie, pour rester honnête. La liste s'est allongée. Guette-Orage, Lac-aux-Lanternes\u{a0}: chaque fois que je me retournais, la même personne était là. Personne ne m'avait jamais rattrapé. Je me disais que c'était agaçant. J'écris ici, où personne ne le lira, que ce n'était pas vrai."), "card:Pecklet"),
        page(T::new("At the door", "Devant la porte"), T::new("Six seals, and there we were at the sealed door. My last try. I had asked that door once, years before, and it doesn't open for no colour. We played. Win or lose, I said, I'd know. Then the door opened on its own and Sable walked out, and she didn't even look at our decks. The seventh face, she said, was never for one colour, nor for none. It's for whoever brings someone else along.", "Six sceaux, et nous voilà devant la porte scellée. Mon dernier essai. J'avais déjà demandé à cette porte, des années plus tôt\u{a0}: elle ne s'ouvre pas pour qui n'a pas de couleur. On a joué. Gagné ou perdu, je saurais. Puis la porte s'est ouverte toute seule, Sable est sortie, et elle n'a même pas regardé nos decks. La septième face, a-t-elle dit, n'a jamais été pour une couleur, ni pour aucune. Elle est pour qui amène quelqu'un avec soi."), "faces"),
        page(T::new("Apprentice", "Apprenti"), T::new("Sable carved a seventh face on the stone by the hall's door. It's still blank. I walk past it every morning with a broom, because Wynne took me on as her apprentice. I sweep, I sort the packs, I deal at the table, and I'm told I'm terrible at dusting. Fair. Turns out the path was never closed. Nobody had walked it with company, that's all. Fancy a game? Loser sweeps.", "Sable a gravé une septième face sur la pierre près de l'entrée de la salle. Elle est encore blanche. Je passe devant chaque matin avec un balai, parce que Wynne m'a pris comme apprenti. Je balaie, je trie les boosters, je donne les cartes à la table, et il paraît que je suis nul pour la poussière. C'est juste. Finalement, le chemin n'a jamais été fermé. Personne ne l'avait pris à deux, voilà tout. Une partie\u{a0}? Le perdant balaie."), "card:Mendlark"),
    ]},
    Book { id: "hearth_tales", family: Family::Tales, title: T::new("Tales by the Hearth", "Contes au coin du feu"), pages: &[
        page(T::new("The kiln that would not light", "Le four qui refusait de prendre"), T::new("When Cinderwick was three houses and a hope, its first kiln would not light. The potters fed it oak, then coal, then their kindest words, and it sulked cold for a month. A girl named Brisa found a clay egg in the quarry ash and, having nowhere warmer to keep it, set it in the kiln's mouth for the night. By morning the egg had cracked, a sooty chick was singing, and the kiln roared. It has never gone out since.", "Quand Mèche-Cendre n'était que trois maisons et un espoir, son premier four refusait de prendre. Les potiers lui donnèrent du chêne, puis du charbon, puis leurs plus douces paroles\u{a0}: il bouda, froid, tout un mois. Une fille nommée Brisa trouva un œuf d'argile dans la cendre de la carrière et, faute d'endroit plus chaud, le posa pour la nuit dans la gueule du four. Au matin, l'œuf s'était fendu, un oisillon couvert de suie chantait, et le four ronflait. Il ne s'est jamais éteint depuis."), "card:Cindrel"),
        page(T::new("The glassblower's bead", "La perle de la souffleuse"), T::new("Old Tamsin the glassblower made one bead a year and gave it to whoever had been kindest to her that year. One winter a Kilnfox crept into her workshop and stole the coal from her furnace, leaving her nothing to work with. She did not chase it. She left a bowl of warm ash by the door instead. In spring the fox came back with a bead of its own blowing: crooked, smoky and perfect. She wore it all her life.", "La vieille Tamsin, souffleuse de verre, ne faisait qu'une perle par an et l'offrait à qui avait été le plus gentil avec elle. Un hiver, un Fournard se glissa dans son atelier et vola le charbon de son four\u{a0}: il ne lui resta plus de quoi travailler. Elle ne le chassa pas. Elle laissa plutôt un bol de cendre tiède près de la porte. Au printemps, le renard revint avec une perle de sa façon, tordue, fumée et parfaite. Elle la porta toute sa vie."), "card:Kilnfox"),
        page(T::new("The quarry race", "La course de la carrière"), T::new("Every year at Emberstep, the quarry folk race from the floor to the top ledge, and every year somebody brings a Flarrow to run beside them, arms back, the way the bird runs. Long ago a miller's son swore he would beat the bird itself. He trained all summer, ran like the wind and lost by a head. The Flarrow waited for him at the top all the same. That is why the winner still waits for the last runner.", "Chaque année, à Pas-de-Braise, les gens de la carrière font la course du fond jusqu'à la plus haute corniche, et chaque année quelqu'un amène un Flambèche pour courir à côté, bras en arrière, comme court l'oiseau. Il y a longtemps, un fils de meunier jura de battre l'oiseau lui-même. Il s'entraîna tout l'été, courut comme le vent et perdit d'une tête. Le Flambèche l'attendit quand même au sommet. Voilà pourquoi le vainqueur attend toujours le dernier coureur."), "card:Flarrow"),
        page(T::new("Why glass sings", "Pourquoi le verre chante"), T::new("Wendell will tell you that cooling glass sings, and if you sit by the racks at night you will hear it. The old story says the first glass ever blown in Cinderwick was made from sand the tide had carried all the way from the Saltreach, and it has been homesick ever since. As it cools, every pane hums a little of the sea. Nobody has proved it. Nobody has proved it wrong, either.", "Wendell vous le dira\u{a0}: le verre qui refroidit chante, et si vous vous asseyez la nuit près des claies, vous l'entendrez. Selon la vieille histoire, le tout premier verre soufflé à Mèche-Cendre venait d'un sable que la marée avait porté depuis la Côte Salée, et il a le mal du pays depuis. En refroidissant, chaque vitre fredonne un peu de la mer. Personne ne l'a jamais prouvé. Personne n'a prouvé le contraire non plus."), "face:ember"),
    ]},
    Book { id: "lantern_tales", family: Family::Tales, title: T::new("Lantern Lake Tales", "Contes du lac aux lanternes"), pages: &[
        page(T::new("The lantern that came back", "La lanterne revenue"), T::new("Every dusk the lantern-makers of Lanternmere set their lanterns on the lake, and every dawn the wind has carried them off somewhere. One lantern, they say, came back. A girl had written her grandmother's name on it the night the old woman left this world. Three years later, on a still night, it drifted up to her pier, its paper whole, its light still burning. She did not relight it. She did not need to.", "Chaque soir, les lanterniers de Lac-aux-Lanternes posent leurs lanternes sur le lac, et chaque matin le vent les a emportées ailleurs. Une lanterne, dit-on, est revenue. Une fille y avait écrit le nom de sa grand-mère, le soir où la vieille dame avait quitté ce monde. Trois ans plus tard, par une nuit sans vent, la lanterne vint toucher son ponton, le papier intact, la flamme encore vive. Elle ne la ralluma pas. Elle n'en avait pas besoin."), "card:Wispun"),
        page(T::new("The moth that carried a name", "La phalène qui portait un nom"), T::new("In the Hushlands, what you cannot say aloud, you whisper to a moth. A shy ferryman once whispered a name to the moth at his lamp: the name of the girl who sold bread on the far shore. The moth crossed the lake and landed on her shoulder, and she brushed it away without a thought. But the next morning she crossed to buy his fish, and she never stopped crossing. Moths, they say there, are patient.", "Aux Terres du Murmure, ce qu'on ne peut pas dire tout haut, on le chuchote à une phalène. Un jour, un passeur timide chuchota un nom à la phalène de sa lampe\u{a0}: celui de la fille qui vendait le pain sur l'autre rive. La phalène traversa le lac et se posa sur son épaule\u{a0}; elle la chassa sans y penser. Mais le lendemain matin, elle traversa pour acheter son poisson, et ne cessa plus jamais de traverser. Les phalènes, dit-on là-bas, sont patientes."), "card:Moonmoth"),
        page(T::new("The Moonwell", "Le Puits-de-Lune"), T::new("In the walled garden at the end of the Hushlands there is a sunken well that holds no water, only moonlight. Drop a pebble in and you will hear nothing. Drop a dream in and, the gardeners say, it comes back better. Lumen will not tell you whether she believes it. But every night she sits on its rim until the moonflowers open, and nobody has ever seen her drop anything in.", "Dans le jardin clos, au bout des Terres du Murmure, il y a un puits creusé qui ne contient pas d'eau, seulement du clair de lune. Lâchez-y un caillou, vous n'entendrez rien. Lâchez-y un rêve et, disent les jardiniers, il vous revient en mieux. Lumen ne vous dira pas si elle y croit. Mais chaque nuit, elle s'assoit sur la margelle jusqu'à ce que les fleurs de lune s'ouvrent, et personne ne l'a jamais vue y jeter quoi que ce soit."), "face:dream"),
        page(T::new("The lantern path", "Le chemin des lanternes"), T::new("At night a line of lantern rafts crosses Lanternmere's lake, straight as a ruled line, from the village to the Moonwell shore. The lantern-maker launches them, but she will tell you she does not steer them. The old ferry hands say the rafts line up for anyone walking toward someone, and drift apart for anyone walking away. Watch the next time you cross. If the path holds under your feet, somebody is waiting at the end.", "La nuit, une file de radeaux-lanternes traverse le lac de Lac-aux-Lanternes, droite comme un trait de règle, du village jusqu'à la rive du Puits-de-Lune. C'est la lanternière qui les met à l'eau, mais elle vous dira qu'elle ne les guide pas. Les vieux passeurs racontent que les radeaux s'alignent pour qui marche vers quelqu'un, et se dispersent pour qui s'éloigne. Regardez bien, la prochaine fois que vous traverserez. Si le chemin tient sous vos pas, quelqu'un vous attend au bout."), "card:Gloamowl"),
    ]},
];

pub fn book(id: &str) -> Option<&'static Book> {
    BOOKS.iter().find(|b| b.id == id)
}

/// The progress flag set once a book has been opened.
pub fn read_flag(id: &str) -> String {
    format!("read_{id}")
}

pub fn is_read(p: &Progress, id: &str) -> bool {
    p.has_flag(&read_flag(id))
}

/// How many of [`BOOKS`] have been read.
pub fn read_count(p: &Progress) -> usize {
    BOOKS.iter().filter(|b| is_read(p, b.id)).count()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::set::CARDS;

    fn texts(b: &Book) -> impl Iterator<Item = &'static str> + '_ {
        std::iter::once(b.title)
            .chain(b.pages.iter().flat_map(|p| [p.heading, p.text]))
            .flat_map(|t| [t.en, t.fr])
    }

    #[test]
    fn enough_books_of_each_family() {
        let n = |f| BOOKS.iter().filter(|b| b.family == f).count();
        assert!(n(Family::Rules) >= 3, "rules books");
        assert!(n(Family::World) >= 5, "world books");
        assert!(BOOKS.len() >= 8);
    }

    #[test]
    fn book_ids_are_unique_flag_names() {
        for (i, b) in BOOKS.iter().enumerate() {
            assert!(
                !b.id.is_empty()
                    && b.id
                        .bytes()
                        .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == b'_'),
                "{}",
                b.id
            );
            assert!(BOOKS[..i].iter().all(|o| o.id != b.id), "{} twice", b.id);
            assert!(book(b.id).is_some());
        }
    }

    #[test]
    fn every_book_has_pages_in_both_languages() {
        for b in BOOKS {
            assert!(b.pages.len() >= 3, "{}: {} pages", b.id, b.pages.len());
            for t in texts(b) {
                assert!(!t.trim().is_empty(), "{}: an empty text", b.id);
            }
            for p in b.pages {
                // A page fits its half of the spread at 150 % text.
                for t in [p.text.en, p.text.fr] {
                    let words = t.split_whitespace().count();
                    assert!(
                        words <= 110,
                        "{}: {words} words on “{}”",
                        b.id,
                        p.heading.en
                    );
                }
            }
        }
    }

    #[test]
    fn player_text_never_says_ai() {
        for b in BOOKS {
            for t in texts(b) {
                let bad = t
                    .split(|c: char| !c.is_alphanumeric())
                    .any(|w| w == "AI" || w == "IA");
                assert!(!bad, "{}: {t}", b.id);
            }
        }
    }

    #[test]
    fn illustrations_name_real_cards_and_types() {
        for b in BOOKS {
            for p in b.pages {
                let ok = match p.art.split_once(':') {
                    Some(("card", name)) => CARDS.iter().any(|c| c.name == name),
                    Some(("face", f)) => FACES.contains(&f),
                    None => matches!(p.art, "" | "faces" | "board"),
                    _ => false,
                };
                assert!(ok, "{}: bad art {}", b.id, p.art);
            }
        }
    }

    #[test]
    fn a_book_is_read_once_its_flag_is_set() {
        let mut p = Progress::default();
        let id = BOOKS[0].id;
        assert!(!is_read(&p, id));
        assert_eq!(read_count(&p), 0);
        p.apply(&format!("flag:{}", read_flag(id))).unwrap();
        assert!(is_read(&p, id));
        assert_eq!(read_count(&p), 1);
        // An old save has no such flag: nothing read, nothing lost.
        assert_eq!(read_count(&Progress::decode("c:100")), 0);
    }
}
